-- Stage-7 state-keyed patrol wrapper for probe_stage_speed.lua.
--
-- The stock frame/loop patrols change direction as a function of time or loop
-- count. A ROM with different renderer cadence therefore consumes a different
-- movement sequence. This wrapper changes direction only at exact world-X
-- endpoints, while observing the native $0ABB input join. During play,
-- emu:setKeys is the sole stimulus.
--
-- Equal-world mode (STAGE7_WORLD_IMAGE): at the first play-phase input join
-- both ROMs receive the same native world image (D800-D8FF scene/player
-- state, DC00-DCFF entity tables, FFD4-FFD5 frame counters) captured from the
-- stock ROM, then the RNG cursor FFD1 is set to STAGE7_WORLD_SEED. Stock and
-- DX therefore start the measured patrol from identical game state. Every
-- run dumps the post-injection image to OUT .. '.world.bin' so the verifier
-- can prove the four traces started equal.

local base_path = assert(os.getenv("STAGE7_STATE_PATROL_BASE_PROBE"))
local file = assert(io.open(base_path, "r"))
local source = file:read("*a")
file:close()

local count
source, count = source:gsub(
  '    if phase == "sync" then\n      phase = "play"\n      play_frames = 0\n      previous_scx = emu:read8%(0xFF43%)\n      previous_scy = emu:read8%(0xFF42%)\n    end',
  '    if phase == "sync" then return end')
assert(count == 1, "checked main-loop sync anchor changed")

source, count = source:gsub(
  '  %-%- The two stock entries publish H[^\n]*',
  function()
    return [[
  local WORLD_RANGES = {{0xD800, 0x100}, {0xDC00, 0x100}, {0xFFCB, 1}, {0xFFD4, 2}}
  local coordinate = assert(io.open(OUT .. '.coordinate.tsv', 'w'))
  local prof = assert(io.open(OUT .. '.prof.tsv', 'w'))
  local active = false
  local function hit(pc)
    return function()
      if phase ~= 'play' then return end
      if pc == 0x06D1 then active = true end
      if not active then return end
      prof:write(string.format('%d\t%X\t%d\n', play_frames, pc, emu:currentCycle()))
      if pc == 0x081D then active = false end
    end
  end
  local B0 = {0x58,0x5A,0x5D,0x99,0x9B,0x9D,0x9F,0xA1,0xA3,0xA5,0xA7,0x6D1,0x6D2,0x6D3,0x6D4,0x6D5,0x6D6,0x6D7,0x6D8,0x6DB,0x6DC,0x6DF,0x6E2,0x6E4,0x6E5,0x6E7,0x6E9,0x6EA,0x6EC,0x6EE,0x6F0,0x6F1,0x6F3,0x6F5,0x6F7,0x6F9,0x6FB,0x6FD,0x6FF,0x700,0x702,0x705,0x706,0x708,0x70B,0x70C,0x70E,0x710,0x713,0x714,0x717,0x719,0x71B,0x71D,0x71F,0x721,0x723,0x724,0x727,0x72A,0x72B,0x72C,0x72E,0x731,0x732,0x734,0x735,0x737,0x739,0x73B,0x73D,0x73E,0x740,0x742,0x744,0x746,0x748,0x749,0x74B,0x74C,0x74E,0x750,0x751,0x753,0x754,0x756,0x758,0x759,0x75C,0x75F,0x760,0x763,0x764,0x766,0x767,0x76A,0x76B,0x76D,0x770,0x773,0x774,0x776,0x777,0x77A,0x77B,0x77D,0x780,0x783,0x784,0x786,0x789,0x78A,0x78D,0x78E,0x790,0x791,0x792,0x794,0x795,0x798,0x799,0x79B,0x79D,0x79E,0x7A0,0x7A3,0x7A4,0x7A7,0x7A9,0x7AC,0x7AE,0x7B0,0x7B3,0x7B4,0x7B6,0x7B9,0x7BA,0x7BD,0x7BF,0x7C0,0x7C3,0x7C6,0x7C9,0x7CA,0x7CC,0x7CD,0x7D0,0x7D1,0x7D3,0x7D4,0x7D5,0x7D7,0x7DA,0x7DD,0x7DE,0x7E0,0x7E1,0x7E4,0x7E5,0x7E7,0x7E8,0x7E9,0x7EB,0x7EE,0x7F1,0x7F2,0x7F4,0x7F5,0x7F7,0x7F8,0x7F9,0x7FC,0x7FD,0x800,0x801,0x803,0x806,0x809,0x80B,0x80E,0x810,0x811,0x813,0x814,0x816,0x817,0x818,0x819,0x81A,0x81B,0x81C,0x81D,0x81E,0x81F,0x821,0x822,0x823,0x824,0x826,0x827,0x829,0x82B,0x82E,0x831,0x832,0x834,0x837,0x86C,0x86E,0x86F,0x870,0x871,0x874,0x875,0x878,0x87A,0x87B,0x87D,0x87F,0x880,0x883,0x884,0x885,0x887,0x88A,0x88C,0x88D,0x88F,0x890,0x891,0x893,0x894,0x896,0x897,0x899,0x89B,0x89C,0x89F,0x8A0,0x8A1,0x8A2,0x8A3,0x8A4,0x8A5,0x8A8,0x8A9,0x8AA,0x8AB,0x8AC,0x8AD,0x8AF,0x8B2,0x8B3,0x8B4,0x8B5,0x8B6,0x8B7,0x8B8,0x8B9,0x8BB,0x8BC,0x8BF,0x8C0,0x8C1,0x8C2,0x8C3,0x8C5,0x8C6,0x8C8,0x8CA,0x8CB,0x8CE,0x8CF,0x8D0,0x8D1,0x8D3,0x8D6,0x8D8,0x8D9,0x8DB,0x8DC,0x8DD,0x8DF,0x8E0,0x8E2,0x8E3,0x8E5,0x8E7,0x8EA,0x8EC,0x8ED,0x8EF,0x8F0,0x8F1,0x8F3,0x8F4,0x8F6,0x8F7,0x9B3,0x9B4,0x9B5,0x9B6,0x9B7,0x9B8,0x9B9,0x9BA,0x9BC,0x9BD,0xFF80}
